module Table = struct
  type ('k, 'v) t = { mutable buckets : ('k * 'v) list array; mutable size : int }

  let create () = { buckets = Array.make 4 []; size = 0 }
  let index t k = Hashtbl.hash k mod Array.length t.buckets

  let resize t =
    let old = t.buckets in
    t.buckets <- Array.make (2 * Array.length old) [];
    Array.iter
      (List.iter (fun (k, v) ->
           let i = index t k in
           t.buckets.(i) <- (k, v) :: t.buckets.(i)))
      old

  let replace t k v =
    let i = index t k in
    let rest = List.remove_assoc k t.buckets.(i) in
    if List.length rest = List.length t.buckets.(i) then t.size <- t.size + 1;
    t.buckets.(i) <- (k, v) :: rest;
    if t.size > 2 * Array.length t.buckets then resize t

  let find_opt t k = List.assoc_opt k t.buckets.(index t k)
  let length t = t.size
  let bucket_count t = Array.length t.buckets

  (* RI: size is the number of entries, each lives in the bucket its key hashes to. *)
  let rep_ok t =
    let total = ref 0 in
    Array.iteri
      (fun i bucket ->
        List.iter (fun (k, _) -> incr total; assert (index t k = i)) bucket)
      t.buckets;
    !total = t.size
end

let () =
  let t = Table.create () in
  for k = 1 to 100 do Table.replace t k (k * k) done;
  Printf.printf "%d %d\n" (Table.length t) (Table.bucket_count t);
  Printf.printf "%s %s\n"
    (match Table.find_opt t 42 with Some v -> string_of_int v | None -> "missing")
    (match Table.find_opt t 500 with Some v -> string_of_int v | None -> "missing");
  Table.replace t 42 0;
  Printf.printf "%d %s\n" (Table.length t) (match Table.find_opt t 42 with Some v -> string_of_int v | None -> "missing");
  Printf.printf "invariant holds: %b\n" (Table.rep_ok t)

