let cost = ref 0

type 'a q = { front : 'a list; back : 'a list }

let empty = { front = []; back = [] }
let push x q = incr cost; { q with back = x :: q.back }

let pop q =
  incr cost;
  match q.front with
  | x :: front -> Some (x, { q with front })
  | [] -> (
      match List.rev q.back with
      | [] -> None
      | x :: front ->
          cost := !cost + List.length q.back;
          Some (x, { front; back = [] }))

let drain q =
  let rec go q n = match pop q with None -> n | Some (_, q') -> go q' (n + 1) in
  go q 0

let () =
  let n = 1000 in
  cost := 0;
  let q = ref empty in
  for i = 1 to n do q := push i !q done;
  let popped = drain !q in
  let ops = (2 * n) + 1 in
  Printf.printf "popped %d, total cost %d for %d operations\n" popped !cost ops;
  Printf.printf "amortised cost at most 3 per operation: %b\n" (!cost <= 3 * ops);
  (* Reusing one old version defeats the bound: every pop repeats the reversal. *)
  let full = ref empty in
  for i = 1 to n do full := push i !full done;
  cost := 0;
  for _ = 1 to n do ignore (pop !full) done;
  Printf.printf "reusing one version costs %d for %d pops\n" !cost n

