type 'a stream = Cons of 'a * 'a stream Lazy.t

let rec from n = Cons (n, lazy (from (n + 1)))
let rec take n (Cons (x, rest)) = if n = 0 then [] else x :: take (n - 1) (Lazy.force rest)

let rec filter p (Cons (x, rest)) =
  if p x then Cons (x, lazy (filter p (Lazy.force rest))) else filter p (Lazy.force rest)

let rec sieve (Cons (p, rest)) =
  Cons (p, lazy (sieve (filter (fun n -> n mod p <> 0) (Lazy.force rest))))

let primes = sieve (from 2)
let rec fibs a b = Cons (a, lazy (fibs b (a + b)))

let show l = String.concat " " (List.map string_of_int l)

let () =
  print_endline (show (take 10 primes));
  print_endline (show (take 10 (fibs 0 1)));
  let evaluations = ref 0 in
  let counted = lazy (incr evaluations; 42) in
  ignore (Lazy.force counted);
  ignore (Lazy.force counted);
  Printf.printf "forced twice, evaluated %d time\n" !evaluations;
  let from_seq = List.of_seq (Seq.take 5 (Seq.ints 0)) in
  Printf.printf "Seq: %s\n" (show from_seq)

