let memo_rec f =
  let table = Hashtbl.create 16 in
  let rec self x =
    match Hashtbl.find_opt table x with
    | Some v -> v
    | None ->
        let v = f self x in
        Hashtbl.add table x v;
        v
  in
  self

let naive_calls = ref 0
let rec fib_naive n = incr naive_calls; if n < 2 then n else fib_naive (n - 1) + fib_naive (n - 2)

let memo_calls = ref 0
let fib_memo = memo_rec (fun self n -> incr memo_calls; if n < 2 then n else self (n - 1) + self (n - 2))

let edit_distance s t =
  let computed = ref 0 in
  let distance =
    memo_rec (fun self (i, j) ->
        incr computed;
        if i = 0 then j
        else if j = 0 then i
        else
          let cost = if s.[i - 1] = t.[j - 1] then 0 else 1 in
          min (min (self (i - 1, j) + 1) (self (i, j - 1) + 1)) (self (i - 1, j - 1) + cost))
  in
  let d = distance (String.length s, String.length t) in
  (d, !computed)

let () =
  let a = fib_naive 20 in
  Printf.printf "%d with %d calls\n" a !naive_calls;
  let b = fib_memo 20 in
  Printf.printf "%d with %d calls\n" b !memo_calls;
  let d, entries = edit_distance "kitten" "sitting" in
  Printf.printf "edit distance %d from %d table entries\n" d entries

