type 'a tree = Leaf of 'a | Node of 'a tree * 'a tree
type 'a t = { size : int; tree : 'a tree }

let rec build lo hi f =
  if hi - lo = 1 then Leaf (f lo)
  else
    let mid = (lo + hi) / 2 in
    Node (build lo mid f, build mid hi f)

let init size f = { size; tree = build 0 size f }

let get a i =
  let rec go t lo hi =
    match t with
    | Leaf v -> v
    | Node (l, r) ->
        let mid = (lo + hi) / 2 in
        if i < mid then go l lo mid else go r mid hi
  in
  go a.tree 0 a.size

let set a i v =
  let rec go t lo hi =
    match t with
    | Leaf _ -> Leaf v
    | Node (l, r) ->
        let mid = (lo + hi) / 2 in
        if i < mid then Node (go l lo mid, r) else Node (l, go r mid hi)
  in
  { a with tree = go a.tree 0 a.size }

let right a = match a.tree with Node (_, r) -> r | Leaf _ -> invalid_arg "right"

let () =
  let a0 = init 8 (fun i -> i * i) in
  let a1 = set a0 3 100 in
  Printf.printf "%d %d\n" (get a0 3) (get a1 3);
  Printf.printf "untouched elements agree: %b\n" (get a0 6 = get a1 6);
  let a2 = set a1 1 (-1) in
  Printf.printf "right half shared by all versions: %b\n" (right a0 == right a2);
  Printf.printf "versions all usable: %d %d %d\n" (get a0 1) (get a1 1) (get a2 1)

